#!/bin/sh

# colours: the bases and rules below define every colour; colours.g.sh (generated by colours-derive) holds the results
# before sourcing this file, set colours_dir to the directory containing it and colours.g.sh
# NAME_256=N next to a colour sets its 256-colour value where the hex is not exactly an xterm entry

# bases: the only colours defined by value
# col_black and col_white are bases themselves; base_grey is the neutral one
col_black=#000000
col_white=#FFFFFF
base_grey=#AAAAAA
# the chromatic bases are invented, not colours that appear on screen: "oklch lightness chroma hue"
# a chroma beyond sRGB is allowed; a base as drawn has its chroma reduced until it fits (about the hex in each comment)
base_red="oklch 0.5374 0.273 25.8"	# about #CA1C25
base_orange="oklch 0.7633 0.197 80.6"	# about #E2A628
base_yellow="oklch 0.8947 0.187 109.5"	# about #E6E527
base_green="oklch 0.7591 0.213 144.0"	# about #42D14B
base_blue="oklch 0.7188 0.161 257.2"	# about #69A5FA
base_purple="oklch 0.7092 0.189 313.0"	# about #CA78F4

# rules: one line per derived colour, "name base modifier step"
# a modifier is a chain word, with er or est added for level 2 or 3 (light, lighter, lightest); t = level * step
#   light, dark    OKLCH lightness toward white, toward black by t, chroma kept
#   soft, hard     OKLCH chroma times 1 - t, times 1 + t
#   pale, shade    RGB mixed with white, with black by t
#   muted          RGB mixed with the colour's own grey (0.2126 R + 0.7152 G + 0.0722 B) by t
#   warm, cool     OKLCH hue turned by t degrees toward orange (60), toward blue-cyan (230)
# the same modifier does the same operation in every group; the step may differ by up to 25% from the usual
# (light 0.12, dark 0.12, soft 0.30, hard 0.25, pale 0.20, shade 0.16, muted 0.25, warm 15, cool 15)
colour_rules='
col_red			base_red	soft		0.30
col_bright_red		base_red	lighter		0.15
col_nord11		base_red	paler		0.15
col_nord12		base_red	paler		0.20
col_magenta		base_red	coolest		11.25
col_orange		base_orange	warm		15
col_nord13		base_orange	palest		0.15
col_yellow		base_yellow	harder		0.19
col_bright_yellow	base_yellow	lightest	0.15
col_green		base_green	shader		0.20
col_bright_green	base_green	muteder		0.19
col_nord14		base_green	softest		0.22
col_emerald		base_green	cool		11.25
col_lime		base_green	warm		11.25
col_blue		base_blue	darker		0.12
col_bright_blue		base_blue	dark		0.12
col_nord10		base_blue	shader		0.12
col_nord9		base_blue	mutedest	0.19
col_cyan		base_blue	coolest		15
col_bright_cyan		base_blue	coolest		11.25
col_purple		base_purple	darkest		0.12
col_violet		base_purple	shader		0.14
col_nord15		base_purple	mutedest	0.22
col_bright_purple	base_purple	warm		15
col_bright_black	col_white	shadest		0.20
col_grey_light		col_white	darkest		0.10
col_almost_black	col_black	lighter		0.09
col_dark		col_black	lightest	0.09
col_dark2		col_black	pale		0.183
col_grey		base_grey	shadest		0.20
col_light		base_grey	palest		0.25
'

if [ -z "${colours_dir-}" ]; then
	echo "colours: set colours_dir to the directory containing colours.sh before sourcing it" >&2
	return 1
fi
if [ -f "$colours_dir/colours.g.sh" ]; then
	. "$colours_dir/colours.g.sh"
elif [ -z "${colours_generating-}" ]; then
	echo "colours: $colours_dir/colours.g.sh is missing, run colours-derive" >&2
fi

# 256-colour values where the colour is not exactly an xterm entry; the first sixteen are the terminal palette slots
col_black_256=0
col_red_256=1
col_emerald_256=2
col_yellow_256=3
col_blue_256=4
col_purple_256=5
col_cyan_256=6
col_bright_black_256=8
col_bright_red_256=9
col_bright_green_256=10
col_bright_yellow_256=11
col_bright_blue_256=12
col_bright_purple_256=13
col_bright_cyan_256=14
col_light_256=15
col_green_256=28
col_lime_256=76
col_violet_256=97
col_magenta_256=162

_colour_value() {
	case $1 in
		''|[0-9]*|*[!A-Za-z0-9_]*) echo "colours: bad colour name '$1'" >&2; return 1 ;;
	esac
	eval "_cv=\${$1-}"
	if [ -z "$_cv" ]; then
		echo "colours: unknown colour '$1'" >&2
		return 1
	fi
	case $_cv in
		\#[0-9A-Fa-f][0-9A-Fa-f][0-9A-Fa-f][0-9A-Fa-f][0-9A-Fa-f][0-9A-Fa-f]) ;;
		*) echo "colours: '$1' is not #RRGGBB ($_cv)" >&2; return 1 ;;
	esac
}

_colour_split() {
	_colour_value "$1" || return 1
	_h=${_cv#\#}
	_r=$((0x${_h%????}))
	_g=${_h#??}
	_g=$((0x${_g%??}))
	_b=$((0x${_h#????}))
}

colour_hex() {
	_colour_value "$1" || return 1
	printf '%s\n' "$_cv"
}

_colour_override() {
	eval "_ov=\${$1_$2-}"
	[ -n "$_ov" ]
}

_colour_badoverride() {
	echo "colours: ${1}_$2 must be $3 ($_ov)" >&2
	return 1
}

colour_rgb() {
	_colour_split "$1" || return 1
	printf '%s;%s;%s\n' "$_r" "$_g" "$_b"
}

colour_alpha() {
	_colour_value "$1" || return 1
	printf '%s%s\n' "$_cv" "$2"
}

colour_argb() {
	_colour_value "$1" || return 1
	printf '#%s%s\n' "$2" "${_cv#\#}"
}

_colour_level() {
	if [ "$1" -lt 48 ]; then
		_lv=0
	elif [ "$1" -lt 115 ]; then
		_lv=1
	else
		_lv=$((($1 - 35) / 40))
	fi
}

_colour_levelval() {
	if [ "$1" -eq 0 ]; then
		_lvv=0
	else
		_lvv=$((55 + 40 * $1))
	fi
}

colour_256() {
	_colour_split "$1" || return 1
	if _colour_override "$1" 256; then
		case $_ov in
			*[!0-9]*) _colour_badoverride "$1" 256 "0-255"; return ;;
		esac
		if [ "$_ov" -gt 255 ]; then
			_colour_badoverride "$1" 256 "0-255"
			return
		fi
		printf '%s\n' "$_ov"
		return
	fi
	_colour_level "$_r"; _ri=$_lv; _colour_levelval "$_ri"; _rv=$_lvv
	_colour_level "$_g"; _gi=$_lv; _colour_levelval "$_gi"; _gv=$_lvv
	_colour_level "$_b"; _bi=$_lv; _colour_levelval "$_bi"; _bv=$_lvv
	if [ "$_r" -eq "$_rv" ] && [ "$_g" -eq "$_gv" ] && [ "$_b" -eq "$_bv" ]; then
		printf '%s\n' "$((16 + 36 * _ri + 6 * _gi + _bi))"
		return
	fi
	if [ "$_r" -eq "$_g" ] && [ "$_g" -eq "$_b" ] && [ "$_r" -ge 8 ] && [ "$_r" -le 238 ] && [ $(((_r - 8) % 10)) -eq 0 ]; then
		printf '%s\n' "$((232 + (_r - 8) / 10))"
		return
	fi
	echo "colours: $1 is not an xterm 256 colour, set ${1}_256" >&2
	return 1
}

colours_unload() {
	for _n in $(set | sed -n -e 's/^\(col_[A-Za-z0-9_]*\)=.*/\1/p'); do
		unset "$_n"
	done
	unset base_grey base_red base_orange base_yellow base_green base_blue base_purple colour_rules colours_dir colours_generating
	unset _n _cv _h _r _g _b _ov _lv _lvv _ri _gi _bi _rv _gv _bv _cube
	unset -f colour_hex colour_rgb colour_alpha colour_argb colour_256 _colour_value _colour_split _colour_override _colour_badoverride _colour_level _colour_levelval colours_unload
}
